def _calc_checksum(self, secret):
    if isinstance(secret, str):
        secret = secret.encode('utf-8')
    real_rounds = 1 << self.rounds
    result = hashlib.md5(self.salt.encode('ascii') + secret).digest()
    r = 0
    while r < real_rounds:
        result = hashlib.md5(result + secret).digest()
